"""Validated public URL helpers for links generated by the API."""
from urllib.parse import urlsplit

from app.core.config import settings


def public_app_origin() -> str:
    raw = settings.DOMAIN.strip()
    if not raw:
        raise RuntimeError("The public app domain is not configured.")
    parsed = urlsplit(raw if "://" in raw else f"https://{raw}")
    if parsed.scheme not in ("https", "http") or not parsed.hostname or parsed.username or parsed.password:
        raise RuntimeError("The public app domain is invalid.")
    if parsed.path not in ("", "/") or parsed.query or parsed.fragment:
        raise RuntimeError("The public app domain must be an origin without a path.")
    if parsed.scheme != "https" and parsed.hostname not in ("localhost", "127.0.0.1"):
        raise RuntimeError("The public app domain must use HTTPS.")
    return f"{parsed.scheme}://{parsed.netloc}"
